package probe
import("context";"fmt";"net/http";"time";"github.com/samanramezani1377-hub/crawler-numpo/internal/model";"github.com/samanramezani1377-hub/crawler-numpo/internal/policy")
type Prober struct{Client *http.Client}
func New(t time.Duration)*Prober{return &Prober{&http.Client{Timeout:t,CheckRedirect:func(r *http.Request,v []*http.Request)error{if len(v)>=3{return http.ErrUseLastResponse};return nil}}}}
func(p *Prober)Probe(ctx context.Context,host string)(model.ProbeResult,error){o:=model.ProbeResult{Host:host,Status:"inactive"};for _,s:=range []string{"https","http"}{raw:=s+"://"+host+"/";if e:=policy.ValidateURL(raw);e!=nil{o.Status="error";o.ErrorCode="ssrf_blocked";o.ErrorMessage=e.Error();return o,e};st:=time.Now();req,e:=http.NewRequestWithContext(ctx,http.MethodHead,raw,nil);if e!=nil{continue};resp,e:=p.Client.Do(req);if e!=nil{continue};ms:=time.Since(st).Milliseconds();resp.Body.Close();if s=="https"{o.HTTPSStatus=resp.StatusCode}else{o.HTTPStatus=resp.StatusCode};o.ResponseTimeMS=ms;if resp.StatusCode>=200&&resp.StatusCode<500{o.Status="active";if resp.Request!=nil{o.RedirectTarget=resp.Request.URL.String()};return o,nil}};return o,fmt.Errorf("no usable HTTP response")}
